use xiom.io;

use xiom.string;
fn main() {
  let groceries = ["milk", "eggs", "bread", "apples", "cheese"];

  io.println("Shopping list:");

  for item in groceries {
    let message = string.str_concat("Buy: ", item);
    io.println(message);
  }

  io.println("That's everything!");
}
